<?php
namespace App\Filament\Admin\Resources\RegulatoryReports\Pages;use App\Application\Compliance\RegulatoryReportingService;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\RegulatoryReports\RegulatoryReportRunResource;use Filament\Actions\Action;use Filament\Resources\Pages\ViewRecord;final class ViewRegulatoryReport extends ViewRecord{protected static string$resource=RegulatoryReportRunResource::class;protected function getHeaderActions():array{return[Action::make('approve')->visible(fn()=>$this->record->status==='DRAFT')->action(function(){if(ServiceValidation::run(fn()=>app(RegulatoryReportingService::class)->approve($this->record,auth()->user()))===null)return;}),Action::make('submit')->visible(fn()=>in_array($this->record->status,['APPROVED','RETRY_PENDING'],true))->action(function(){if(ServiceValidation::run(fn()=>app(RegulatoryReportingService::class)->submit($this->record))===null)return;})];}}
